{"source": "def poly(x, a, b, c):
    return a * x + b * x * x + c * x * x * x

def contributions(values, a, b, c, g, mode):
    out = []
    total = 0
    prev = 0
    for i in range(len(values)):
        x = values[i]
        base = poly(x, a, b, c)
        if mode == 0:
            extra = g * x * prev
        else:
            extra = g * x * total
        out.append(base + extra)
        total = total + x
        prev = x
    return out

def cumsum_pass(lst):
    out = []
    s = 0
    for v in lst:
        s = s + v
        out.append(s)
    return out

def apply_passes(lst, n):
    cur = lst
    for _ in range(n):
        cur = cumsum_pass(cur)
    return cur

def evaluate(values, a, b, c, g, mode, passes):
    if len(values) == 0:
        return 0
    contribs = contributions(values, a, b, c, g, mode)
    result = apply_passes(contribs, passes)
    return result[-1]

def search(values):
    coeffs = [-2, -1, 0, 1, 2]
    gs = [-2, -1, 1, 2]
    best = None
    for a in coeffs:
        for b in coeffs:
            for c in coeffs:
                for g in gs:
                    for mode in (0, 1):
                        for passes in (1, 2, 3, 4):
                            val = evaluate(values, a, b, c, g, mode, passes)
                            if best is None or abs(val) < abs(best):
                                best = val
    return best

def investigate(context, acquire):
    values = context["values"]
    if len(values) == 0:
        return 0
    return search(values)
